import { type QrFailureDetails, type QrFailureReason, type QrFailureStage, type QrLoginChannel, type QrPrimaryFailure, type QrState } from './qrTypes';
export declare const terminalState: (state: QrState) => boolean;
/**
 * States where the user is already acting on this QR from their phone. A second login attempt must
 * not pull the rug out from under that, so these keep the 409; every other non-terminal state is an
 * abandoned code and is preemptible. `confirmed` is deliberately absent: it is terminal, it never
 * blocked a new session, and blocking it would 409 anyone who signs out and back in inside the TTL.
 */
export declare const confirmingState: (state: QrState) => boolean;
/** Keeps whatever opaque number the upstream gave us, whichever channel produced the failure. */
export declare const upstreamCodeOf: (error: unknown) => number | undefined;
/**
 * A login failure's optional key. An HTTP failure or a non-zero gateway code takes precedence, so
 * only a business code from an otherwise healthy response counts, and then only when channel, step
 * and number all match a registered entry with a source.
 */
export declare const loginUpstreamErrorKeyOf: (error: unknown, channel: QrLoginChannel | undefined) => string | undefined;
/** Only stable, non-sensitive error categories cross the API boundary. */
export declare const qrFailureReasonOf: (error: unknown) => QrFailureReason;
export declare const safeDiagnosticNumber: (value: unknown) => number | undefined;
export declare const upstreamHttpStatusOf: (error: unknown) => number | undefined;
export declare const QR_FAILURE_STAGES: Set<string>;
export declare const QR_FAILURE_REASONS: Set<string>;
/** Restored records are untrusted. Select and validate only public diagnostic fields. */
export declare const failureDetailsOf: (source: QrFailureDetails) => QrFailureDetails;
export declare const qrFailureDetailsOf: (error: unknown, stage: QrFailureStage, channel?: QrLoginChannel) => QrFailureDetails;
/** What a primary step failed with, in the shape `primaryFailure` carries. */
export declare const primaryFailureOf: (error: unknown, stage: QrFailureStage, channel: QrLoginChannel) => QrPrimaryFailure;
